1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Scenario {
23	  customer: { yearsWithMHPCO: number };
24	  steps: Step[];
25	}
26	
27	export type QuoteResult = { premium: number };
28	export type ClaimResult = { payout: number; remainingCap: number };
29	export type Result = QuoteResult | ClaimResult;
30	
31	export interface ScenarioOutcome {
32	  results: Result[];
33	}
34	
35	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
36	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
37	
38	const BASE_PREMIUM: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	  potion: 40,
43	  rune: 25,
44	  moonstone: 25,
45	};
46	
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const POLICY_FEE = 5;
49	
50	const COMPONENT_TYPES = ["rune", "moonstone"];
51	const BUILDING_BLOCK_SIZE = 3;
52	const BUILDING_BLOCK_BASE_PREMIUM = 60;
53	
54	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
55	
56	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
57	
58	const countOfType = (items: Item[], type: string): number =>
59	  items.filter((item) => item.type === type).length;
60	
61	/**
62	 * Components of one kind are bundled into building blocks of 3, each charged at
63	 * the special block rate; leftovers are charged individually.
64	 */
65	const componentGroupBasePremium = (type: string, count: number): number => {
66	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
67	  const singles = count % BUILDING_BLOCK_SIZE;
68	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
69	};
70	
71	const CURSED_SURCHARGE_RATE = 0.5;
72	
73	/** Risk surcharges attach to the individual item that carries the risk. */
74	const riskMultiplierOf = (item: Item): number => (item.cursed ? 1 + CURSED_SURCHARGE_RATE : 1);
75	
76	/** Main items are priced one by one, straight off the base price list. */
77	const mainItemsPremium = (items: Item[]): number =>
78	  sum(
79	    items
80	      .filter((item) => !isComponent(item))
81	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
82	  );
83	
84	/** Components are priced per kind, so alike ones can bundle into building blocks. */
85	const componentsPremium = (items: Item[]): number =>
86	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
87	
88	const totalBasePremiumOf = (items: Item[]): number =>
89	  mainItemsPremium(items) + componentsPremium(items);
90	
91	const quote = (items: Item[]): QuoteResult => {
92	  const totalBasePremium = totalBasePremiumOf(items);
93	  const withFirstInsuranceSurcharge = totalBasePremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
94	  return { premium: roundUpToWholeG(withFirstInsuranceSurcharge) + POLICY_FEE };
95	};
96	
97	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
98	  const results = scenario.steps.map((step) => {
99	    if (step.op === "quote") return quote(step.items);
100	    throw new Error("claim steps are not implemented yet");
101	  });
102	  return { results };
103	};
